"""Independent reference: runs compilation, changes, brute-force optimum."""
import itertools
import random

U = 1 << 128

def compile_runs(routes):
    """routes: dict (addr, length) -> hop. Returns [(start, hop)] coalesced."""
    events = []
    for (s, ln), hop in routes.items():
        events.append((s, 1, ln, hop))
